def build():
 for lang,c in COPY.items():
  en='/interview-rides/';de='/de/interview-rides/'
  home=OUT/('de/index.html' if lang=='de' else 'index.html')
  source=home.read_text()
  nav=re.search(r'<a class="skip".*?</header>',source,re.S).group(0)
  nav=re.sub(r'<div class="language-switch".*?</div>',f'<div class="language-switch"><a href="{de}" hreflang="de" lang="de">DE</a><span>|</span><a href="{en}" hreflang="en" lang="en">EN</a></div>',nav)
  if 'class="language-switch"' not in nav:
   nav=nav.replace('</header>',f'<div class="language-switch"><a href="{de}" hreflang="de">DE</a><span>|</span><a href="{en}" hreflang="en">EN</a></div></header>')
  footer=re.search(r'<footer>.*?</footer>',source,re.S).group(0)
  esc=lambda x:html.escape(x,quote=True)
  options=''.join(f'<option value="{v}">{esc(label)}</option>' for v,label in zip(['pillion','own','rental'],c['modes']))
  fields=f'''<label for="ride-name">{c['name']} <span aria-hidden="true">*</span></label><input id="ride-name" name="name" autocomplete="name" maxlength="100" required>
<label for="ride-email">{c['email']} <span aria-hidden="true">*</span></label><input id="ride-email" name="email" type="email" autocomplete="email" maxlength="254" required>
<label for="ride-mode">{c['mode']} <span aria-hidden="true">*</span></label><select id="ride-mode" name="mode" required><option value="">{c['empty']}</option>{options}</select>
<label for="ride-topic">{c['topic']} <span aria-hidden="true">*</span></label><p class="field-help" id="topic-help">{c['topichelp']}</p><textarea id="ride-topic" name="topic" rows="4" maxlength="3000" aria-describedby="topic-help" required></textarea>
<label for="ride-region">{c['region']} <span class="optional">({c['optional']})</span></label><input id="ride-region" name="region" maxlength="200">
<label class="ride-consent"><input type="checkbox" name="consent" required><span>{c['consent']}</span></label><p class="ride-privacy">{c['privacy']}</p>
<div class="bot-field" aria-hidden="true"><label for="ride-company">Company</label><input id="ride-company" name="company" tabindex="-1" autocomplete="off"></div>
<button type="submit" class="button">{c['submit']} <span aria-hidden="true">↗</span></button><p id="form-error" role="alert" tabindex="-1" hidden>{c['error']}</p>'''
  body=f'''<main id="main" class="rides-page"><section class="rides-hero"><div class="rides-hero-copy"><p class="eyebrow">INTERVIEW RIDES / KAY LUMMITSCH</p><h1>{c['headline']}</h1><p class="rides-intro">{c['intro']}</p><div class="rides-dates"><span>{c['date']}</span><span>{c['ideas']}</span></div><a class="button" href="#interesse">{c['cta']} <span aria-hidden="true">↗</span></a></div><figure class="rides-hero-image"><img src="/assets/interview-rides-beiz.png" alt="{esc(c['beizalt'])}" width="1672" height="941"><figcaption>{c['caption']}</figcaption></figure></section>
<div class="rides-facts">{''.join('<span>'+x+'</span>' for x in c['facts'])}</div>
<section class="rides-story"><div><p class="eyebrow">{c['eyebrow']}</p><h2>{c['meet']}</h2><p>{c['opening']}</p><p>{c['body']}</p><p>{c['ride']}</p><p class="rides-small">{c['rental']}</p></div><div><figure><img src="/assets/interview-rides-pass.png" alt="{esc(c['passalt'])}" width="1672" height="941" loading="lazy"><figcaption>{c['caption']}</figcaption></figure><p>{c['recording']}</p><p class="rides-excitement">{c['calm']}</p><p class="rides-matt">{c['matt']}</p></div></section>
<section id="interesse" class="rides-signup"><div class="rides-signup-copy"><p class="eyebrow">{c['date']} / {c['ideas']}</p><h2>{c['formtitle']}</h2><p>{c['formintro']}</p><p class="rides-signature">{c['signature']}<br><br>/hugs/kay</p></div><div class="rides-form-wrap"><form id="ride-form" data-language="{lang}">{fields}</form><div id="ride-success" tabindex="-1" role="status" hidden><span class="rides-success-mark" aria-hidden="true">✓</span><h3>{c['success']}</h3><p>{c['successtext']}</p><button id="form-again" class="text-link">{c['again']} →</button></div><p class="ride-newsletter"><a href="{c['home']}#subscribe">{c['newsletter']}</a></p></div></section><a class="rides-back" href="{c['home']}">← {c['back']}</a></main>'''
  head=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Interview Rides | Kay Lummitsch</title><meta name="description" content="{esc(c['intro'])}"><meta name="theme-color" content="#f45b16"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/interview-rides.css"><link rel="canonical" href="https://kaylummitsch.com{c['route']}"><link rel="alternate" hreflang="de" href="https://kaylummitsch.com{de}"><link rel="alternate" hreflang="en" href="https://kaylummitsch.com{en}"><meta property="og:title" content="Interview Rides | Kay Lummitsch"><meta property="og:description" content="{esc(c['intro'])}"><meta property="og:image" content="https://kaylummitsch.com/assets/interview-rides-beiz.png"><script src="/interview-rides.js" defer></script></head>'''
  folder=OUT/c['route'].strip('/');folder.mkdir(parents=True,exist_ok=True)
  (folder/'index.html').write_text(head+'<body>'+nav+body+footer+'</body></html>')
  # Idempotent homepage invitation; preserve all existing sections.
  teaser=f'''<section class="rides-teaser" id="interview-rides"><figure><img src="/assets/interview-rides-beiz.png" alt="{esc(c['beizalt'])}" width="1672" height="941" loading="lazy"><figcaption>{c['caption']}</figcaption></figure><div><p class="eyebrow">INTERVIEW RIDES / {c['date']}</p><h2>{c['headline']}</h2><p>{c['intro']}</p><a class="button" href="{c['route']}">{c['cta']} <span aria-hidden="true">↗</span></a></div></section>'''
  source=re.sub(r'<section class="rides-teaser".*?</section>','',source,flags=re.S)
  source=source.replace('<section class="writing"',teaser+'\n<section class="writing"',1)
  if '/interview-rides.css' not in source:source=source.replace('</head>','<link rel="stylesheet" href="/interview-rides.css"></head>')
  home.write_text(source)

if __name__=='__main__':build()
